model:
class Base {
  baseVal:Int
}

class Left extending Base {
  leftVal:Int
}

class Right extending Base {
  rightVal:Int
}

class Diamond extending Left,Right {
  share Base;
  diamondVal:Int
}

d:Diamond

req d.baseVal > 0

req d.leftVal > 0

req d.rightVal > 0

req d.diamondVal > 0

req d.baseVal = 10
